/** zoom by speed */
export class TuningViewWidthM {
  slow: number;
  fast: number;

  constructor(r: R) {
    this.slow = r.d('slow');
    this.fast = r.d('fast');
  }

  toJson(): Record<string, unknown> {
    return {
      slow: this.slow,
      fast: this.fast,
    };
  }

  /** Value by YAML key, undefined when the key is unknown. */
  get(key: string): number | undefined {
    switch (key) {
      case 'slow':
        return this.slow;
      case 'fast':
        return this.fast;
      default:
        return undefined;
    }
  }

  static readonly keys = ['slow', 'fast'] as const;
}

