/**
 * Landmark models (specs/models.md, Prompts/06-METROPOLE_LANDMARKS3D_PLAN.md); colours in
 * design/tokens.json color.model.
 */
export class TuningModels {
  enabled: boolean;
  /** per landmark */
  maxTris: number;
  /** ceiling for a models.yaml max_tris (Prague Castle grounds) */
  maxTrisException: number;
  cityMaxTris: number;
  /** models.pb after gzip */
  cityMaxBytes: number;
  /** smaller parts and faces are dropped */
  minDetailM: number;
  /** citypack raises min_detail up to this to meet the budget */
  maxDetailM: number;
  detailStepM: number;
  /** W chase view: model within this of the car, footprints beyond */
  nearM: number;
  /** switch back to footprints only beyond near_m + this */
  hysteresisM: number;
  /** W: models drawn at once, the nearest win */
  maxFull: number;
  roofPlanMaxPolys: number;
  /** citypack: vertex weld */
  weldM: number;
  /** citypack: roof plan simplification */
  planSimplifyM: number;
  /** citypack: a pack building at least this covered is replaced */
  replaceShare: number;
  /** validate: part foot vs terrain at its anchor (real metres) */
  footToleranceM: number;
  /** validate: model centre vs landmark point */
  maxOffsetM: number;
  /** citypack: a part whose top is this high above the foot … */
  copperMinTopM: number;
  /** … and whose footprint is at most this × its height has copper roofs */
  copperSlender: number;
  /** W: stone wall texture, one bay (buttress + lancet window) across */
  facadeBayM: number;
  /** W: stone wall texture, one tier of lancet windows up */
  facadeStoreyM: number;
  /** W: roof texture, distance between seams (stripes down the slope) */
  roofSeamM: number;
  /** citypack (v3): bridge deck this close to either end sits on the terrain */
  bridgeEndM: number;
  /** validate (v3): no bridge face from a road surface up to this (game m) */
  bridgeClearM: number;
  /** validate (v3): … nor this close below it (depth fight with the road) */
  bridgeBelowM: number;
  /** citypack (v4): source ground this high above the lowest is an underside (Žižkov pods), not the foot */
  groundFloatM: number;
  /** citypack (v4): models.yaml `parts` also take faces of other groups inside the picked box + this */
  partBoxSlackM: number;

  constructor(r: R) {
    this.enabled = r.b('enabled');
    this.maxTris = r.i('max_tris');
    this.maxTrisException = r.i('max_tris_exception');
    this.cityMaxTris = r.i('city_max_tris');
    this.cityMaxBytes = r.i('city_max_bytes');
    this.minDetailM = r.d('min_detail_m');
    this.maxDetailM = r.d('max_detail_m');
    this.detailStepM = r.d('detail_step_m');
    this.nearM = r.d('near_m');
    this.hysteresisM = r.d('hysteresis_m');
    this.maxFull = r.i('max_full');
    this.roofPlanMaxPolys = r.i('roof_plan_max_polys');
    this.weldM = r.d('weld_m');
    this.planSimplifyM = r.d('plan_simplify_m');
    this.replaceShare = r.d('replace_share');
    this.footToleranceM = r.d('foot_tolerance_m');
    this.maxOffsetM = r.d('max_offset_m');
    this.copperMinTopM = r.d('copper_min_top_m');
    this.copperSlender = r.d('copper_slender');
    this.facadeBayM = r.d('facade_bay_m');
    this.facadeStoreyM = r.d('facade_storey_m');
    this.roofSeamM = r.d('roof_seam_m');
    this.bridgeEndM = r.d('bridge_end_m');
    this.bridgeClearM = r.d('bridge_clear_m');
    this.bridgeBelowM = r.d('bridge_below_m');
    this.groundFloatM = r.d('ground_float_m');
    this.partBoxSlackM = r.d('part_box_slack_m');
  }

  toJson(): Record<string, unknown> {
    return {
      enabled: this.enabled,
      max_tris: this.maxTris,
      max_tris_exception: this.maxTrisException,
      city_max_tris: this.cityMaxTris,
      city_max_bytes: this.cityMaxBytes,
      min_detail_m: this.minDetailM,
      max_detail_m: this.maxDetailM,
      detail_step_m: this.detailStepM,
      near_m: this.nearM,
      hysteresis_m: this.hysteresisM,
      max_full: this.maxFull,
      roof_plan_max_polys: this.roofPlanMaxPolys,
      weld_m: this.weldM,
      plan_simplify_m: this.planSimplifyM,
      replace_share: this.replaceShare,
      foot_tolerance_m: this.footToleranceM,
      max_offset_m: this.maxOffsetM,
      copper_min_top_m: this.copperMinTopM,
      copper_slender: this.copperSlender,
      facade_bay_m: this.facadeBayM,
      facade_storey_m: this.facadeStoreyM,
      roof_seam_m: this.roofSeamM,
      bridge_end_m: this.bridgeEndM,
      bridge_clear_m: this.bridgeClearM,
      bridge_below_m: this.bridgeBelowM,
      ground_float_m: this.groundFloatM,
      part_box_slack_m: this.partBoxSlackM,
    };
  }
}
